void
Test::Intf::dispatch(Ice::IncomingRequest& request, std::function<void(Ice::OutgoingResponse)> sendResponse)
{
    static constexpr std::array<std::string_view, 17> allOperations{"context", "cookie", "current", "del", "ice_id", "ice_ids", "ice_isA", "ice_ping", "inS", "istr", "op", "opField", "opOut", "response", "sync", "typeId", "upCast"};

    const Ice::Current& current = request.current();
    auto r = std::equal_range(allOperations.begin(), allOperations.end(), current.operation); // NOLINT(modernize-use-ranges)
    if (r.first == r.second)
    {
        sendResponse(Ice::makeOutgoingResponse(std::make_exception_ptr(Ice::OperationNotExistException{__FILE__, __LINE__}), current));
        return;
    }

    switch (r.first - allOperations.begin())
    {
        case 0:
        {
            _iceD_context(request, std::move(sendResponse));
            break;
        }
        case 1:
        {
            _iceD_cookie(request, std::move(sendResponse));
            break;
        }
        case 2:
        {
            _iceD_current(request, std::move(sendResponse));
            break;
        }
        case 3:
        {
            _iceD_del(request, std::move(sendResponse));
            break;
        }
        case 4:
        {
            _iceD_ice_id(request, std::move(sendResponse));
            break;
        }
        case 5:
        {
            _iceD_ice_ids(request, std::move(sendResponse));
            break;
        }
        case 6:
        {
            _iceD_ice_isA(request, std::move(sendResponse));
            break;
        }
        case 7:
        {
            _iceD_ice_ping(request, std::move(sendResponse));
            break;
        }
        case 8:
        {
            _iceD_inS(request, std::move(sendResponse));
            break;
        }
        case 9:
        {
            _iceD_istr(request, std::move(sendResponse));
            break;
        }
        case 10:
        {
            _iceD_op(request, std::move(sendResponse));
            break;
        }
        case 11:
        {
            _iceD_opField(request, std::move(sendResponse));
            break;
        }
        case 12:
        {
            _iceD_opOut(request, std::move(sendResponse));
            break;
        }
        case 13:
        {
            _iceD_response(request, std::move(sendResponse));
            break;
        }
        case 14:
        {
            _iceD_sync(request, std::move(sendResponse));
            break;
        }
        case 15:
        {
            _iceD_typeId(request, std::move(sendResponse));
            break;
        }
        case 16:
        {
            _iceD_upCast(request, std::move(sendResponse));
            break;
        }
        default:
        {
            assert(false);
            sendResponse(Ice::makeOutgoingResponse(std::make_exception_ptr(Ice::OperationNotExistException{__FILE__, __LINE__}), current));
        }
    }
}

